144	func newExpertsStyles(w io.Writer) expertsStyles {
145		return expertsStylesForColor(shouldUseColor(w))
146	}
147	
148	func expertsStylesForColor(useColor bool) expertsStyles {
149		styles := expertsStyles{colorEnabled: useColor}
150		if !useColor {
151			return styles
152		}
153	
154		styles.title = lipgloss.NewStyle().Foreground(lipgloss.Color(palette.Accent)).Bold(true)
155		styles.agent = lipgloss.NewStyle().Foreground(lipgloss.Color(palette.Accent)).Bold(true)
156		styles.label = lipgloss.NewStyle().Foreground(lipgloss.Color(palette.Info))
157		styles.facet = lipgloss.NewStyle().Foreground(lipgloss.Color(palette.Blue))
158		styles.muted = lipgloss.NewStyle().Foreground(lipgloss.Color(palette.Muted))
159		styles.file = lipgloss.NewStyle().Foreground(lipgloss.Color(palette.Info))
160		styles.bullet = lipgloss.NewStyle().Foreground(lipgloss.Color(palette.Accent))
161		return styles
162	}
