164	func (s expertsStyles) render(style lipgloss.Style, text string) string {
165		if !s.colorEnabled {
166			return text
167		}
168		return style.Render(text)
169	}
170	
171	// link renders text in the given style with an OSC 8 terminal hyperlink to url
172	// attached. Links are only emitted when styling is enabled (a capable, non-piped
173	// terminal); otherwise it falls back to plain styled text so scripts and dumb
174	// terminals are unaffected.
175	func (s expertsStyles) link(style lipgloss.Style, url, text string) string {
176		if !s.colorEnabled || strings.TrimSpace(url) == "" {
177			return s.render(style, text)
178		}
179		return style.Hyperlink(url).Render(text)
180	}
