182	func newExpertsCmd() *cobra.Command {
183		f := &expertsFlags{limit: 8}
184		cmd := &cobra.Command{
185			Use:   "experts [scope-or-query]",
186			Short: "Rank agent provenance for code scopes",
187			Long: `Rank which agents, skills, and tools have provenance over a code scope — who
188	and what has touched the given code.
189	
190	The argument is either a single scope (a file or directory path) or a
191	natural-language query. A scope or query is required unless --staged is set,
192	which uses the staged file paths as scopes instead. Results come from the
193	entire-api cell keyed on the repo, so the repo must be mirrored.`,
194			Example: "  entire experts src/payments --json\n  entire experts \"who owns token refresh\" --json\n  entire experts --staged",
195			Hidden:  true,
196			Args:    cobra.ArbitraryArgs,
197			RunE: func(cmd *cobra.Command, args []string) error {
198				return runExperts(cmd.Context(), cmd.OutOrStdout(), cmd.ErrOrStderr(), args, f)
199			},
200		}
201		cmd.Flags().StringVar(&f.repo, "repo", "", "Repository as owner/repo")
202		cmd.Flags().StringVar(&f.branch, "branch", "", "Branch to inspect")
203		cmd.Flags().IntVar(&f.limit, "limit", expertsDefaultLimit, "Maximum profiles to return (1–20; values above 20 are clamped)")
204		cmd.Flags().BoolVar(&f.json, "json", false, "Print JSON")
205		cmd.Flags().BoolVar(&f.staged, "staged", false, "Use staged file paths as scopes")
206		cmd.Flags().BoolVar(&f.tui, "tui", false, "Browse provenance in an interactive viewer (TTY only)")
207		cmd.Flags().BoolVar(&f.insecureHTTP, "insecure-http-auth", false, "Allow plain-HTTP auth (local dev only)")
208		if err := cmd.Flags().MarkHidden("insecure-http-auth"); err != nil {
209			panic(fmt.Sprintf("hide experts insecure auth flag: %v", err))
210		}
211		return cmd
212	}
