214	func runExperts(ctx context.Context, out, errOut io.Writer, args []string, f *expertsFlags) error {
215		if f.staged && strings.TrimSpace(f.repo) != "" {
216			return errors.New("--staged cannot be used with --repo")
217		}
218		if f.limit <= 0 {
219			f.limit = expertsDefaultLimit
220		}
221		if f.limit > expertsMaxLimit {
222			f.limit = expertsMaxLimit
223		}
224	
225		// The data API (entire-api) is repo-ULID keyed. --repo may be a ULID (used
226		// directly) or an owner/repo, which we resolve to its ULID after the client
227		// exists (via the caller's accessible-repo list). With no --repo we derive
228		// owner/repo from the git origin.
229		repoOverride := strings.TrimSpace(f.repo)
230		repoIsULID := looksLikeULID(repoOverride)
231		var repoFullName string
232		if !repoIsULID {
233			var err error
234			repoFullName, err = resolveExpertsRepo(ctx, f.repo)
235			if err != nil {
236				return err
237			}
238		}
239	
240		req := expertsRequest{Limit: f.limit, EvidenceLimit: 3}
241		if strings.TrimSpace(f.branch) != "" {
242			req.Branch = strings.TrimSpace(f.branch)
243		}
244	
245		if f.staged {
246			scopes, err := stagedExpertScopes(ctx)
247			if err != nil {
248				return err
249			}
250			if len(scopes) == 0 {
251				fmt.Fprintln(errOut, "No staged files found.")
252				return NewSilentError(errors.New("no staged files"))
253			}
254			req.Scopes = scopes
255		} else {
256			input := strings.TrimSpace(strings.Join(args, " "))
257			if input == "" {
258				return errors.New("scope or query required unless --staged is set")
259			}
260			if strings.TrimSpace(f.repo) != "" && looksLikeExpertPath(input) {
261				req.Scopes = []string{normalizeExpertScope(input)}
262			} else {
263				local, err := localExpertScope(ctx, input)
264				if err != nil {
265					return err
266				}
267				if local.isLocal {
268					if !repoIsULID && repoOverride != "" && local.validateRepo {
269						currentRepo, err := resolveExpertsRepo(ctx, "")
270						if err == nil && !strings.EqualFold(currentRepo, repoFullName) {
271							return fmt.Errorf("local path belongs to %s, not --repo %s", currentRepo, repoFullName)
272						}
273					}
274					req.Scopes = []string{local.scope}
275				} else {
276					query := input
277					req.Query = &query
278				}
279			}
280		}
281	
282		// Identify the repo for cell routing: a ULID goes on the ulid arg, an
283		// owner/repo on the fullName arg. The client uses whichever is set to reach
284		// the cell that hosts the repo's processing placement.
285		cellFullName, cellULID := "", ""
286		if repoIsULID {
287			cellULID = repoOverride
288		} else {
289			cellFullName = repoFullName
290		}
291		client, err := newExpertsAPIClient(ctx, f.insecureHTTP, cellFullName, cellULID)
292		if err != nil {
293			// Not-onboarded is the most common way cell resolution fails, and its
294			// raw chain is internal resolution steps; render it like the trail
295			// commands do instead of burying it under another wrap. cellFullName is
296			// "" for the ULID form, where renderRepoNotOnboarded falls back to
297			// naming no repo.
298			if rendered := renderRepoNotOnboarded(errOut, cellFullName, err); rendered != nil {
299				return rendered
300			}
301			return fmt.Errorf("create experts API client: %w", err)
302		}
303	
304		repoID := repoOverride
305		if !repoIsULID {
306			repoID, err = resolveExpertsRepoID(ctx, client, repoFullName)
307			if err != nil {
308				return err
309			}
310		}
311	
312		resp, err := client.Post(ctx, expertsAPIPath(repoID), req)
313		if err != nil {
314			return fmt.Errorf("post experts request: %w", err)
315		}
316		defer resp.Body.Close()
317	
318		if err := api.CheckResponse(resp); err != nil {
319			var httpErr *api.HTTPError
320			if errors.As(err, &httpErr) {
321				// A natural-language query needs code search on the cell. When it
322				// isn't available the cell returns 503 — sometimes with only a bare
323				// "Service Unavailable" body — so treat any 503 on a query as the
324				// code-search-unavailable case. Path scopes don't need code search
325				// and fall through to the generic error below.
326				if httpErr.StatusCode == http.StatusServiceUnavailable && req.Query != nil {
327					fmt.Fprintln(errOut, "Code search is not available for natural-language experts queries on this backend.")
328					return NewSilentError(err)
329				}
330				// entire-api returns 404 "repo not in this region" when the repo is
331				// homed in a different cell than the one reached. Surface that as an
332				// actionable region hint instead of the raw service-to-service text.
333				if httpErr.StatusCode == http.StatusNotFound &&
334					strings.Contains(strings.ToLower(httpErr.Message), "region") {
335					fmt.Fprintln(errOut, "This repo appears to be homed in a different Entire region than the cell this command reached; cross-region experts routing may be incomplete.")
336					return NewSilentError(err)
337				}
338			}
339			return fmt.Errorf("fetch experts: %w", err)
340		}
341	
342		var decoded expertsResponse
343		if err := api.DecodeJSON(resp, &decoded); err != nil {
344			return fmt.Errorf("decode experts response: %w", err)
345		}
346	
347		if f.json {
348			enc := json.NewEncoder(out)
349			enc.SetIndent("", "  ")
350			if err := enc.Encode(decoded); err != nil {
351				return fmt.Errorf("write experts JSON: %w", err)
352			}
353			return nil
354		}
355	
356		// The interactive viewer is opt-in and only runs on a real terminal with
357		// results to show. Piped/accessible output and empty results always fall
358		// through to the deterministic plain renderer so agents and scripts get
359		// stable output.
360		if f.tui && len(decoded.Profiles) > 0 && interactive.IsTerminalWriter(out) && !IsAccessibleMode() {
361			return runExpertsTUI(decoded, shouldUseColor(out))
362		}
363	
364		renderExperts(out, decoded)
365		return nil
366	}
367	
368	func resolveExpertsRepo(ctx context.Context, override string) (string, error) {
369		if strings.TrimSpace(override) != "" {
370			return parseExpertsRepo(override)
371		}
372		_, owner, repo, err := gitremote.ResolveRemoteRepo(ctx, "origin")
373		if err != nil {
374			return "", fmt.Errorf("resolve repo from origin: %w", err)
375		}
376		if owner == "" || repo == "" {
377			return "", errors.New("could not resolve owner/repo from origin")
378		}
379		return owner + "/" + repo, nil
380	}
381	
382	func parseExpertsRepo(value string) (string, error) {
383		trimmed := strings.Trim(strings.TrimSpace(value), "/")
384		parts := strings.Split(trimmed, "/")
385		if len(parts) == 3 && parts[0] == "gh" {
386			parts = parts[1:]
387		}
388		if len(parts) != 2 || parts[0] == "" || parts[1] == "" {
389			return "", fmt.Errorf("invalid --repo %q (use owner/repo)", value)
390		}
391		return parts[0] + "/" + strings.TrimSuffix(parts[1], ".git"), nil
392	}
393	
394	func expertsAPIPath(repoID string) string {
395		return expertsReposListPath + "/" + url.PathEscape(repoID) + "/experts"
396	}
397	
398	// resolveExpertsRepoID maps an owner/repo to its repo ULID for the entire-api
399	// data plane, which is ULID-keyed. It reads the caller's accessible-repo list
400	// (GET /api/v1/repos) and matches on full name — an authz-safe resolution (the
401	// list only contains repos the caller can read, so it never reveals a repo they
402	// can't see). A ULID is passed straight through by the caller, so this is only
403	// hit for the owner/repo form.
404	func resolveExpertsRepoID(ctx context.Context, client expertsAPIClient, fullName string) (string, error) {
405		repos, err := listExpertsAccessibleRepos(ctx, client)
406		if err != nil {
407			return "", err
408		}
409		want := strings.ToLower(fullName)
410		for _, r := range repos {
411			if r.ID != "" && strings.ToLower(r.FullName) == want {
412				return r.ID, nil
413			}
414		}
415		return "", fmt.Errorf("repo %q was not found on the entire-api cell this command reached. It may be homed in another Entire region (cross-region experts routing may be incomplete), not onboarded to Entire, or outside your access", fullName)
416	}
417	
418	type expertsRepoListItem struct {
419		ID       string `json:"id"`
420		FullName string `json:"full_name"`
421	}
422	
423	// listExpertsAccessibleRepos returns every repo the caller can read on this data
424	// API. entire-api's GET /repos currently returns the full SpiceDB-filtered set in
425	// one response (no page_token), but the loop is forward-compatible if pagination
426	// is added — same pattern as fetchAllPages in core list commands.
427	func listExpertsAccessibleRepos(ctx context.Context, client expertsAPIClient) ([]expertsRepoListItem, error) {
428		return fetchAllPages(ctx, func(ctx context.Context, cursor string) ([]expertsRepoListItem, string, error) {
429			path := expertsReposListPath
430			if cursor != "" {
431				path += "?" + url.Values{"page_token": {cursor}}.Encode()
432			}
433			resp, err := client.Get(ctx, path)
434			if err != nil {
435				return nil, "", fmt.Errorf("list repos: %w", err)
436			}
437			defer resp.Body.Close()
438			if err := api.CheckResponse(resp); err != nil {
439				return nil, "", fmt.Errorf("list repos: %w", err)
440			}
441			var body struct {
442				Repos         []expertsRepoListItem `json:"repos"`
443				NextPageToken string                `json:"next_page_token,omitempty"`
444			}
445			if err := api.DecodeJSON(resp, &body); err != nil {
446				return nil, "", fmt.Errorf("decode repos: %w", err)
447			}
448			return body.Repos, body.NextPageToken, nil
449		})
450	}
451	
452	// expertsWebBaseURL is the origin used to build user-facing session links.
453	//
454	// Session links must point at the real Entire web app, not at whatever data API
455	// the CLI happens to be talking to. So:
456	//   - ENTIRE_WEB_BASE_URL wins when set (e.g. http://localhost:5173 for a local
457	//     frontend during dev).
458	//   - otherwise, if the API base is itself an entire.io host (prod/staging), use
459	//     it (frontend and API share that origin).
460	//   - otherwise (local dev API like 127.0.0.1) fall back to the canonical
461	//     https://entire.io so links still resolve to the proper site.
462	func expertsWebBaseURL() string {
463		if raw := strings.TrimSpace(os.Getenv("ENTIRE_WEB_BASE_URL")); raw != "" {
464			return strings.TrimRight(raw, "/")
465		}
466		if base := strings.TrimRight(api.BaseURL(), "/"); isEntireWebHost(base) {
467			return base
468		}
469		return strings.TrimRight(api.DefaultBaseURL, "/")
470	}
471	
472	func isEntireWebHost(base string) bool {
473		u, err := url.Parse(base)
474		if err != nil {
475			return false
476		}
477		host := strings.ToLower(u.Hostname())
478		return host == "entire.io" || strings.HasSuffix(host, ".entire.io")
479	}
480	
481	// expertsSessionURL builds the entire.io web URL for a session, matching the
482	// frontend route /gh/:org/:repo/session/:sessionId. Returns "" when the inputs
483	// can't form a valid link.
484	func expertsSessionURL(repoFullName, sessionID string) string {
485		sessionID = strings.TrimSpace(sessionID)
486		owner, repo, ok := strings.Cut(repoFullName, "/")
487		if !ok || owner == "" || repo == "" || sessionID == "" {
488			return ""
489		}
490		return fmt.Sprintf("%s/gh/%s/%s/session/%s",
491			expertsWebBaseURL(), url.PathEscape(owner), url.PathEscape(repo), url.PathEscape(sessionID))
492	}
493	
494	func localExpertScope(ctx context.Context, input string) (expertLocalScopeResult, error) {
495		root, err := paths.WorktreeRoot(ctx)
496		if err != nil {
497			if looksLikeExpertPath(input) {
498				return expertLocalScopeResult{
499					scope: normalizeExpertScope(input), isLocal: true,
500				}, nil
501			}
502			return expertLocalScopeResult{}, nil
503		}
504	
505		candidates := make([]string, 0, 2)
506		if filepath.IsAbs(input) {
507			candidates = append(candidates, input)
508		} else {
509			cwdAbs, err := filepath.Abs(input)
510			if err != nil {
511				return expertLocalScopeResult{}, fmt.Errorf("resolve cwd-relative path: %w", err)
512			}
513			candidates = append(candidates, cwdAbs, filepath.Join(root, input))
514		}
515		candidates = uniqueStrings(candidates)
516	
517		for _, candidate := range candidates {
518			info, err := os.Stat(candidate)
519			if err != nil {
520				if os.IsNotExist(err) {
521					continue
522				}
523				return expertLocalScopeResult{}, fmt.Errorf("stat local scope: %w", err)
524			}
525			scope, err := localPathScope(root, candidate, input)
526			if err != nil {
527				return expertLocalScopeResult{}, err
528			}
529			if info.IsDir() && !strings.HasSuffix(scope, "/") {
530				scope += "/"
531			}
532			return expertLocalScopeResult{scope: scope, isLocal: true, validateRepo: true}, nil
533		}
534	
535		if looksLikeExpertPath(input) {
536			missingCandidates := make([]string, 0, 3)
537			if filepath.IsAbs(input) {
538				missingCandidates = append(missingCandidates, input)
539			} else {
540				cwdAbs, err := filepath.Abs(input)
541				if err != nil {
542					return expertLocalScopeResult{}, fmt.Errorf("resolve cwd-relative path: %w", err)
543				}
544				missingCandidates = append(missingCandidates, cwdAbs, filepath.Join(root, input))
545			}
546			for _, candidate := range uniqueStrings(missingCandidates) {
547				scope, err := localPathScope(root, candidate, input)
548				if err != nil {
549					continue
550				}
551				return expertLocalScopeResult{scope: scope, isLocal: true}, nil
552			}
553			return expertLocalScopeResult{
554				scope: normalizeExpertScope(input), isLocal: true,
555			}, nil
556		}
557		return expertLocalScopeResult{}, nil
558	}
559	
560	func localPathScope(root, candidate, original string) (string, error) {
561		rel, err := filepath.Rel(canonicalPathForRel(root), canonicalPathForRel(candidate))
562		if err != nil {
563			return "", fmt.Errorf("relativize local scope: %w", err)
564		}
565		if rel == "." {
566			return "./", nil
567		}
568		if strings.HasPrefix(rel, ".."+string(filepath.Separator)) || rel == ".." {
569			return "", fmt.Errorf("path %q is outside the git worktree", original)
570		}
571		return filepath.ToSlash(rel), nil
572	}
573	
574	func canonicalPathForRel(path string) string {
575		resolved, err := filepath.EvalSymlinks(path)
576		if err == nil {
577			return resolved
578		}
579	
580		var missing []string
581		current := path
582		for {
583			parent := filepath.Dir(current)
584			base := filepath.Base(current)
585			if parent == current {
586				return path
587			}
588			missing = append([]string{base}, missing...)
589			resolvedParent, err := filepath.EvalSymlinks(parent)
590			if err == nil {
591				return filepath.Join(append([]string{resolvedParent}, missing...)...)
592			}
593			current = parent
594		}
595	}
596	
597	func uniqueStrings(values []string) []string {
598		seen := make(map[string]bool, len(values))
599		out := make([]string, 0, len(values))
600		for _, value := range values {
601			if seen[value] {
602				continue
603			}
604			seen[value] = true
605			out = append(out, value)
606		}
607		return out
608	}
609	
610	func looksLikeExpertPath(input string) bool {
611		trimmed := strings.TrimSpace(input)
612		if trimmed == "" || strings.ContainsAny(trimmed, " \t\n\r") {
613			return false
614		}
615		return strings.ContainsAny(trimmed, `/\`) ||
616			strings.HasPrefix(trimmed, ".") ||
617			strings.HasSuffix(trimmed, "/") ||
618			filepath.Ext(trimmed) != ""
619	}
620	
621	func normalizeExpertScope(input string) string {
622		scope := strings.TrimSpace(filepath.ToSlash(input))
623		scope = strings.TrimPrefix(scope, "./")
624		scope = strings.TrimLeft(scope, "/")
625		return scope
626	}
627	
628	func stagedExpertScopes(ctx context.Context) ([]string, error) {
629		cmd := exec.CommandContext(ctx, "git", "diff", "--cached", "--name-only", "--diff-filter=ACMRD")
630		output, err := cmd.Output()
631		if err != nil {
632			return nil, fmt.Errorf("read staged files: %w", err)
633		}
634		return parseGitStagedScopeLines(string(output)), nil
635	}
636	
637	// parseGitStagedScopeLines normalizes git name-only output into repo-relative
638	// path scopes. Windows git may emit CRLF line endings; strip them before split.
639	func parseGitStagedScopeLines(raw string) []string {
640		trimmed := strings.TrimSpace(raw)
641		trimmed = strings.ReplaceAll(trimmed, "\r\n", "\n")
642		lines := strings.Split(trimmed, "\n")
643		scopes := make([]string, 0, len(lines))
644		seen := make(map[string]bool, len(lines))
645		for _, line := range lines {
646			scope := strings.TrimSpace(filepath.ToSlash(line))
647			if scope == "" || seen[scope] {
648				continue
649			}
650			seen[scope] = true
651			scopes = append(scopes, scope)
652		}
653		return scopes
654	}
655	
656	func renderExperts(w io.Writer, resp expertsResponse) {
657		renderExpertsWithStyles(w, resp, newExpertsStyles(w))
658	}
659	
660	func renderExpertsWithStyles(w io.Writer, resp expertsResponse, styles expertsStyles) {
661		scopeLabel := strings.Join(resp.Scopes, ", ")
662		if resp.Query != nil && strings.TrimSpace(*resp.Query) != "" {
663			scopeLabel = *resp.Query
664		}
665		if scopeLabel == "" {
666			scopeLabel = resp.RepoFullName
667		}
668		if len(resp.Profiles) == 0 {
669			fmt.Fprintf(w, "No agent provenance found for %s.\n", styles.render(styles.file, scopeLabel))
670			return
671		}
672	
673		fmt.Fprintf(w, "%s for %s", styles.render(styles.title, "Agent provenance"), styles.render(styles.file, resp.RepoFullName))
674		if resp.Branch != "" {
675			fmt.Fprintf(w, " %s", styles.render(styles.muted, "("+resp.Branch+")"))
676		}
677		fmt.Fprintln(w)
678		fmt.Fprintln(w)
679	
680		for i, profile := range resp.Profiles {
681			if i > 0 {
682				fmt.Fprintln(w)
683			}
684			fmt.Fprintf(w, "%s\n", styles.render(styles.agent, profile.AgentLabel))
685			fmt.Fprintf(w, "  %s: %d sessions, %d matching checkpoints, %d steps", styles.render(styles.label, "evidence"), profile.SessionCount, profile.CheckpointCount, profile.StepCount)
686			if profile.AttributionAgentLines != nil {
687				fmt.Fprintf(w, ", %d agent-attributed lines", *profile.AttributionAgentLines)
688			}
689			fmt.Fprintln(w)
690			writeFacetLineWithStyles(w, "skills", profile.Skills, styles)
691			writeFacetLineWithStyles(w, "tools", profile.ToolMix, styles)
692			writeFacetLineWithStyles(w, "mcp", profile.MCPServers, styles)
693			if len(profile.MatchedFiles) > 0 {
694				fmt.Fprintf(w, "  %s: %s\n", styles.render(styles.label, "files"), strings.Join(renderExpertFiles(profile.MatchedFiles, styles), ", "))
695			}
696			for _, session := range profile.Sessions {
697				sessionURL := expertsSessionURL(resp.RepoFullName, session.SessionID)
698				fmt.Fprintf(w, "  %s %s", styles.render(styles.bullet, "-"), styles.link(styles.facet, sessionURL, session.DisplayName))
699				if session.CheckpointCount > 0 || session.StepCount > 0 {
700					fmt.Fprintf(w, " %s %s", styles.render(styles.muted, "-"), styles.render(styles.muted, fmt.Sprintf("%d checkpoints, %d steps", session.CheckpointCount, session.StepCount)))
701				}
702				fmt.Fprintln(w)
703			}
704		}
705	}
706	
707	func writeFacetLineWithStyles(w io.Writer, label string, facets []expertsFacetCount, styles expertsStyles) {
708		if len(facets) == 0 {
709			return
710		}
711		trimmedLabel := strings.TrimSpace(label)
712		indent := label[:len(label)-len(strings.TrimLeft(label, " \t"))]
713		if indent == "" {
714			indent = "  "
715		}
716		parts := make([]string, 0, len(facets))
717		for _, facet := range facets {
718			if styles.colorEnabled {
719				parts = append(parts, styles.render(styles.facet, facet.Name)+styles.render(styles.muted, fmt.Sprintf(" (%d)", facet.Count)))
720				continue
721			}
722			parts = append(parts, fmt.Sprintf("%s (%d)", facet.Name, facet.Count))
723		}
724		fmt.Fprintf(w, "%s%s: %s\n", indent, styles.render(styles.label, trimmedLabel), strings.Join(parts, ", "))
725	}
726	
727	func renderExpertFiles(files []string, styles expertsStyles) []string {
728		if !styles.colorEnabled {
729			return files
730		}
731		rendered := make([]string, 0, len(files))
732		for _, file := range files {
733			rendered = append(rendered, styles.render(styles.file, file))
734		}
735		return rendered
736	}
737

