package cli

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"os"
	"os/exec"
	"path/filepath"
	"strings"

	"charm.land/lipgloss/v2"
	"github.com/entireio/cli/cmd/entire/cli/api"
	"github.com/entireio/cli/cmd/entire/cli/gitremote"
	"github.com/entireio/cli/cmd/entire/cli/interactive"
	"github.com/entireio/cli/cmd/entire/cli/palette"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/spf13/cobra"
)

type expertsAPIClient interface {
	Get(ctx context.Context, path string) (*http.Response, error)
	Post(ctx context.Context, path string, body any) (*http.Response, error)
}

// newExpertsAPIClient builds the entire-api cell client. fullName (owner/repo)
// or ulid identifies the repo so the client can route to the cell that hosts
// it; one of them is required (see NewAuthenticatedEntireAPICellClient).
var newExpertsAPIClient = func(ctx context.Context, insecureHTTP bool, fullName, ulid string) (expertsAPIClient, error) {
	return NewAuthenticatedEntireAPICellClient(ctx, insecureHTTP, fullName, ulid)
}

func setExpertsClientFactoryForTest(
	t interface{ Helper() },
	fn func(context.Context, bool, string, string) (expertsAPIClient, error),
) func() {
	t.Helper()
	prev := newExpertsAPIClient
	newExpertsAPIClient = fn
	return func() { newExpertsAPIClient = prev }
}

type expertsFlags struct {
	repo         string
	branch       string
	limit        int
	json         bool
	staged       bool
	tui          bool
	insecureHTTP bool
}

const (
	expertsDefaultLimit  = 8
	expertsMaxLimit      = 20
	expertsReposListPath = "/api/v1/repos"
)

// expertLocalScopeResult is the outcome of interpreting a scope argument as a
// local filesystem path (vs a natural-language query).
type expertLocalScopeResult struct {
	scope        string
	isLocal      bool
	validateRepo bool // when true, cross-check git origin against --repo
}

type expertsRequest struct {
	Scopes        []string `json:"scopes,omitempty"`
	Query         *string  `json:"query,omitempty"`
	Branch        string   `json:"branch,omitempty"`
	Limit         int      `json:"limit,omitempty"`
	EvidenceLimit int      `json:"evidence_limit,omitempty"`
}

type expertsResponse struct {
	RepoFullName string           `json:"repo_full_name"`
	Scopes       []string         `json:"scopes"`
	Query        *string          `json:"query"`
	Branch       string           `json:"branch"`
	Source       string           `json:"source"`
	Profiles     []expertsProfile `json:"profiles"`
}

type expertsFacetCount struct {
	Name  string `json:"name"`
	Count int    `json:"count"`
}

type expertsProfile struct {
	AgentID                   string                `json:"agent_id"`
	AgentLabel                string                `json:"agent_label"`
	RawAgents                 []string              `json:"raw_agents"`
	Models                    []string              `json:"models"`
	Labels                    []expertsFacetCount   `json:"labels"`
	Skills                    []expertsFacetCount   `json:"skills"`
	ToolMix                   []expertsFacetCount   `json:"tool_mix"`
	MCPServers                []expertsFacetCount   `json:"mcp_servers"`
	TranscriptTokens          int                   `json:"transcript_tokens"`
	FilesChanged              int                   `json:"files_changed"`
	LastActivityAt            string                `json:"last_activity_at"`
	SessionCount              int                   `json:"session_count"`
	CheckpointCount           int                   `json:"checkpoint_count"`
	StepCount                 int                   `json:"step_count"`
	AttributionAgentLines     *int                  `json:"attribution_agent_lines"`
	AttributionTotalCommitted *int                  `json:"attribution_total_committed"`
	MatchedFiles              []string              `json:"matched_files"`
	ExactFileMatches          int                   `json:"exact_file_matches"`
	PrefixFileMatches         int                   `json:"prefix_file_matches"`
	Sessions                  []expertsEvidenceItem `json:"sessions"`
}

type expertsEvidenceItem struct {
	SessionID                 string   `json:"session_id"`
	DisplayName               string   `json:"display_name"`
	Agent                     *string  `json:"agent"`
	Model                     *string  `json:"model"`
	LastActivityAt            string   `json:"last_activity_at"`
	CheckpointCount           int      `json:"checkpoint_count"`
	StepCount                 int      `json:"step_count"`
	AttributionAgentLines     *int     `json:"attribution_agent_lines,omitempty"`
	AttributionTotalCommitted *int     `json:"attribution_total_committed,omitempty"`
	MatchedFiles              []string `json:"matched_files"`
	ExactFileMatches          int      `json:"exact_file_matches"`
	PrefixFileMatches         int      `json:"prefix_file_matches"`
	CheckpointIDs             []string `json:"checkpoint_ids"`
}

type expertsStyles struct {
	colorEnabled bool

	title  lipgloss.Style
	agent  lipgloss.Style
	label  lipgloss.Style
	facet  lipgloss.Style
	muted  lipgloss.Style
	file   lipgloss.Style
	bullet lipgloss.Style
}

func newExpertsStyles(w io.Writer) expertsStyles {
	return expertsStylesForColor(shouldUseColor(w))
}

func expertsStylesForColor(useColor bool) expertsStyles {
	styles := expertsStyles{colorEnabled: useColor}
	if !useColor {
		return styles
	}

	styles.title = lipgloss.NewStyle().Foreground(lipgloss.Color(palette.Accent)).Bold(true)
	styles.agent = lipgloss.NewStyle().Foreground(lipgloss.Color(palette.Accent)).Bold(true)
	styles.label = lipgloss.NewStyle().Foreground(lipgloss.Color(palette.Info))
	styles.facet = lipgloss.NewStyle().Foreground(lipgloss.Color(palette.Blue))
	styles.muted = lipgloss.NewStyle().Foreground(lipgloss.Color(palette.Muted))
	styles.file = lipgloss.NewStyle().Foreground(lipgloss.Color(palette.Info))
	styles.bullet = lipgloss.NewStyle().Foreground(lipgloss.Color(palette.Accent))
	return styles
}

func (s expertsStyles) render(style lipgloss.Style, text string) string {
	if !s.colorEnabled {
		return text
	}
	return style.Render(text)
}

// link renders text in the given style with an OSC 8 terminal hyperlink to url
// attached. Links are only emitted when styling is enabled (a capable, non-piped
// terminal); otherwise it falls back to plain styled text so scripts and dumb
// terminals are unaffected.
func (s expertsStyles) link(style lipgloss.Style, url, text string) string {
	if !s.colorEnabled || strings.TrimSpace(url) == "" {
		return s.render(style, text)
	}
	return style.Hyperlink(url).Render(text)
}

func newExpertsCmd() *cobra.Command {
	f := &expertsFlags{limit: 8}
	cmd := &cobra.Command{
		Use:   "experts [scope-or-query]",
		Short: "Rank agent provenance for code scopes",
		Long: `Rank which agents, skills, and tools have provenance over a code scope — who
and what has touched the given code.

The argument is either a single scope (a file or directory path) or a
natural-language query. A scope or query is required unless --staged is set,
which uses the staged file paths as scopes instead. Results come from the
entire-api cell keyed on the repo, so the repo must be mirrored.`,
		Example: "  entire experts src/payments --json\n  entire experts \"who owns token refresh\" --json\n  entire experts --staged",
		Hidden:  true,
		Args:    cobra.ArbitraryArgs,
		RunE: func(cmd *cobra.Command, args []string) error {
			return runExperts(cmd.Context(), cmd.OutOrStdout(), cmd.ErrOrStderr(), args, f)
		},
	}
	cmd.Flags().StringVar(&f.repo, "repo", "", "Repository as owner/repo")
	cmd.Flags().StringVar(&f.branch, "branch", "", "Branch to inspect")
	cmd.Flags().IntVar(&f.limit, "limit", expertsDefaultLimit, "Maximum profiles to return (1–20; values above 20 are clamped)")
	cmd.Flags().BoolVar(&f.json, "json", false, "Print JSON")
	cmd.Flags().BoolVar(&f.staged, "staged", false, "Use staged file paths as scopes")
	cmd.Flags().BoolVar(&f.tui, "tui", false, "Browse provenance in an interactive viewer (TTY only)")
	cmd.Flags().BoolVar(&f.insecureHTTP, "insecure-http-auth", false, "Allow plain-HTTP auth (local dev only)")
	if err := cmd.Flags().MarkHidden("insecure-http-auth"); err != nil {
		panic(fmt.Sprintf("hide experts insecure auth flag: %v", err))
	}
	return cmd
}

func runExperts(ctx context.Context, out, errOut io.Writer, args []string, f *expertsFlags) error {
	if f.staged && strings.TrimSpace(f.repo) != "" {
		return errors.New("--staged cannot be used with --repo")
	}
	if f.limit <= 0 {
		f.limit = expertsDefaultLimit
	}
	if f.limit > expertsMaxLimit {
		f.limit = expertsMaxLimit
	}

	// The data API (entire-api) is repo-ULID keyed. --repo may be a ULID (used
	// directly) or an owner/repo, which we resolve to its ULID after the client
	// exists (via the caller's accessible-repo list). With no --repo we derive
	// owner/repo from the git origin.
	repoOverride := strings.TrimSpace(f.repo)
	repoIsULID := looksLikeULID(repoOverride)
	var repoFullName string
	if !repoIsULID {
		var err error
		repoFullName, err = resolveExpertsRepo(ctx, f.repo)
		if err != nil {
			return err
		}
	}

	req := expertsRequest{Limit: f.limit, EvidenceLimit: 3}
	if strings.TrimSpace(f.branch) != "" {
		req.Branch = strings.TrimSpace(f.branch)
	}

	if f.staged {
		scopes, err := stagedExpertScopes(ctx)
		if err != nil {
			return err
		}
		if len(scopes) == 0 {
			fmt.Fprintln(errOut, "No staged files found.")
			return NewSilentError(errors.New("no staged files"))
		}
		req.Scopes = scopes
	} else {
		input := strings.TrimSpace(strings.Join(args, " "))
		if input == "" {
			return errors.New("scope or query required unless --staged is set")
		}
		if strings.TrimSpace(f.repo) != "" && looksLikeExpertPath(input) {
			req.Scopes = []string{normalizeExpertScope(input)}
		} else {
			local, err := localExpertScope(ctx, input)
			if err != nil {
				return err
			}
			if local.isLocal {
				if !repoIsULID && repoOverride != "" && local.validateRepo {
					currentRepo, err := resolveExpertsRepo(ctx, "")
					if err == nil && !strings.EqualFold(currentRepo, repoFullName) {
						return fmt.Errorf("local path belongs to %s, not --repo %s", currentRepo, repoFullName)
					}
				}
				req.Scopes = []string{local.scope}
			} else {
				query := input
				req.Query = &query
			}
		}
	}

	// Identify the repo for cell routing: a ULID goes on the ulid arg, an
	// owner/repo on the fullName arg. The client uses whichever is set to reach
	// the cell that hosts the repo's processing placement.
	cellFullName, cellULID := "", ""
	if repoIsULID {
		cellULID = repoOverride
	} else {
		cellFullName = repoFullName
	}
	client, err := newExpertsAPIClient(ctx, f.insecureHTTP, cellFullName, cellULID)
	if err != nil {
		// Not-onboarded is the most common way cell resolution fails, and its
		// raw chain is internal resolution steps; render it like the trail
		// commands do instead of burying it under another wrap. cellFullName is
		// "" for the ULID form, where renderRepoNotOnboarded falls back to
		// naming no repo.
		if rendered := renderRepoNotOnboarded(errOut, cellFullName, err); rendered != nil {
			return rendered
		}
		return fmt.Errorf("create experts API client: %w", err)
	}

	repoID := repoOverride
	if !repoIsULID {
		repoID, err = resolveExpertsRepoID(ctx, client, repoFullName)
		if err != nil {
			return err
		}
	}

	resp, err := client.Post(ctx, expertsAPIPath(repoID), req)
	if err != nil {
		return fmt.Errorf("post experts request: %w", err)
	}
	defer resp.Body.Close()

	if err := api.CheckResponse(resp); err != nil {
		var httpErr *api.HTTPError
		if errors.As(err, &httpErr) {
			// A natural-language query needs code search on the cell. When it
			// isn't available the cell returns 503 — sometimes with only a bare
			// "Service Unavailable" body — so treat any 503 on a query as the
			// code-search-unavailable case. Path scopes don't need code search
			// and fall through to the generic error below.
			if httpErr.StatusCode == http.StatusServiceUnavailable && req.Query != nil {
				fmt.Fprintln(errOut, "Code search is not available for natural-language experts queries on this backend.")
				return NewSilentError(err)
			}
			// entire-api returns 404 "repo not in this region" when the repo is
			// homed in a different cell than the one reached. Surface that as an
			// actionable region hint instead of the raw service-to-service text.
			if httpErr.StatusCode == http.StatusNotFound &&
				strings.Contains(strings.ToLower(httpErr.Message), "region") {
				fmt.Fprintln(errOut, "This repo appears to be homed in a different Entire region than the cell this command reached; cross-region experts routing may be incomplete.")
				return NewSilentError(err)
			}
		}
		return fmt.Errorf("fetch experts: %w", err)
	}

	var decoded expertsResponse
	if err := api.DecodeJSON(resp, &decoded); err != nil {
		return fmt.Errorf("decode experts response: %w", err)
	}

	if f.json {
		enc := json.NewEncoder(out)
		enc.SetIndent("", "  ")
		if err := enc.Encode(decoded); err != nil {
			return fmt.Errorf("write experts JSON: %w", err)
		}
		return nil
	}

	// The interactive viewer is opt-in and only runs on a real terminal with
	// results to show. Piped/accessible output and empty results always fall
	// through to the deterministic plain renderer so agents and scripts get
	// stable output.
	if f.tui && len(decoded.Profiles) > 0 && interactive.IsTerminalWriter(out) && !IsAccessibleMode() {
		return runExpertsTUI(decoded, shouldUseColor(out))
	}

	renderExperts(out, decoded)
	return nil
}

func resolveExpertsRepo(ctx context.Context, override string) (string, error) {
	if strings.TrimSpace(override) != "" {
		return parseExpertsRepo(override)
	}
	_, owner, repo, err := gitremote.ResolveRemoteRepo(ctx, "origin")
	if err != nil {
		return "", fmt.Errorf("resolve repo from origin: %w", err)
	}
	if owner == "" || repo == "" {
		return "", errors.New("could not resolve owner/repo from origin")
	}
	return owner + "/" + repo, nil
}

func parseExpertsRepo(value string) (string, error) {
	trimmed := strings.Trim(strings.TrimSpace(value), "/")
	parts := strings.Split(trimmed, "/")
	if len(parts) == 3 && parts[0] == "gh" {
		parts = parts[1:]
	}
	if len(parts) != 2 || parts[0] == "" || parts[1] == "" {
		return "", fmt.Errorf("invalid --repo %q (use owner/repo)", value)
	}
	return parts[0] + "/" + strings.TrimSuffix(parts[1], ".git"), nil
}

func expertsAPIPath(repoID string) string {
	return expertsReposListPath + "/" + url.PathEscape(repoID) + "/experts"
}

// resolveExpertsRepoID maps an owner/repo to its repo ULID for the entire-api
// data plane, which is ULID-keyed. It reads the caller's accessible-repo list
// (GET /api/v1/repos) and matches on full name — an authz-safe resolution (the
// list only contains repos the caller can read, so it never reveals a repo they
// can't see). A ULID is passed straight through by the caller, so this is only
// hit for the owner/repo form.
func resolveExpertsRepoID(ctx context.Context, client expertsAPIClient, fullName string) (string, error) {
	repos, err := listExpertsAccessibleRepos(ctx, client)
	if err != nil {
		return "", err
	}
	want := strings.ToLower(fullName)
	for _, r := range repos {
		if r.ID != "" && strings.ToLower(r.FullName) == want {
			return r.ID, nil
		}
	}
	return "", fmt.Errorf("repo %q was not found on the entire-api cell this command reached. It may be homed in another Entire region (cross-region experts routing may be incomplete), not onboarded to Entire, or outside your access", fullName)
}

type expertsRepoListItem struct {
	ID       string `json:"id"`
	FullName string `json:"full_name"`
}

// listExpertsAccessibleRepos returns every repo the caller can read on this data
// API. entire-api's GET /repos currently returns the full SpiceDB-filtered set in
// one response (no page_token), but the loop is forward-compatible if pagination
// is added — same pattern as fetchAllPages in core list commands.
func listExpertsAccessibleRepos(ctx context.Context, client expertsAPIClient) ([]expertsRepoListItem, error) {
	return fetchAllPages(ctx, func(ctx context.Context, cursor string) ([]expertsRepoListItem, string, error) {
		path := expertsReposListPath
		if cursor != "" {
			path += "?" + url.Values{"page_token": {cursor}}.Encode()
		}
		resp, err := client.Get(ctx, path)
		if err != nil {
			return nil, "", fmt.Errorf("list repos: %w", err)
		}
		defer resp.Body.Close()
		if err := api.CheckResponse(resp); err != nil {
			return nil, "", fmt.Errorf("list repos: %w", err)
		}
		var body struct {
			Repos         []expertsRepoListItem `json:"repos"`
			NextPageToken string                `json:"next_page_token,omitempty"`
		}
		if err := api.DecodeJSON(resp, &body); err != nil {
			return nil, "", fmt.Errorf("decode repos: %w", err)
		}
		return body.Repos, body.NextPageToken, nil
	})
}

// expertsWebBaseURL is the origin used to build user-facing session links.
//
// Session links must point at the real Entire web app, not at whatever data API
// the CLI happens to be talking to. So:
//   - ENTIRE_WEB_BASE_URL wins when set (e.g. http://localhost:5173 for a local
//     frontend during dev).
//   - otherwise, if the API base is itself an entire.io host (prod/staging), use
//     it (frontend and API share that origin).
//   - otherwise (local dev API like 127.0.0.1) fall back to the canonical
//     https://entire.io so links still resolve to the proper site.
func expertsWebBaseURL() string {
	if raw := strings.TrimSpace(os.Getenv("ENTIRE_WEB_BASE_URL")); raw != "" {
		return strings.TrimRight(raw, "/")
	}
	if base := strings.TrimRight(api.BaseURL(), "/"); isEntireWebHost(base) {
		return base
	}
	return strings.TrimRight(api.DefaultBaseURL, "/")
}

func isEntireWebHost(base string) bool {
	u, err := url.Parse(base)
	if err != nil {
		return false
	}
	host := strings.ToLower(u.Hostname())
	return host == "entire.io" || strings.HasSuffix(host, ".entire.io")
}

// expertsSessionURL builds the entire.io web URL for a session, matching the
// frontend route /gh/:org/:repo/session/:sessionId. Returns "" when the inputs
// can't form a valid link.
func expertsSessionURL(repoFullName, sessionID string) string {
	sessionID = strings.TrimSpace(sessionID)
	owner, repo, ok := strings.Cut(repoFullName, "/")
	if !ok || owner == "" || repo == "" || sessionID == "" {
		return ""
	}
	return fmt.Sprintf("%s/gh/%s/%s/session/%s",
		expertsWebBaseURL(), url.PathEscape(owner), url.PathEscape(repo), url.PathEscape(sessionID))
}

func localExpertScope(ctx context.Context, input string) (expertLocalScopeResult, error) {
	root, err := paths.WorktreeRoot(ctx)
	if err != nil {
		if looksLikeExpertPath(input) {
			return expertLocalScopeResult{
				scope: normalizeExpertScope(input), isLocal: true,
			}, nil
		}
		return expertLocalScopeResult{}, nil
	}

	candidates := make([]string, 0, 2)
	if filepath.IsAbs(input) {
		candidates = append(candidates, input)
	} else {
		cwdAbs, err := filepath.Abs(input)
		if err != nil {
			return expertLocalScopeResult{}, fmt.Errorf("resolve cwd-relative path: %w", err)
		}
		candidates = append(candidates, cwdAbs, filepath.Join(root, input))
	}
	candidates = uniqueStrings(candidates)

	for _, candidate := range candidates {
		info, err := os.Stat(candidate)
		if err != nil {
			if os.IsNotExist(err) {
				continue
			}
			return expertLocalScopeResult{}, fmt.Errorf("stat local scope: %w", err)
		}
		scope, err := localPathScope(root, candidate, input)
		if err != nil {
			return expertLocalScopeResult{}, err
		}
		if info.IsDir() && !strings.HasSuffix(scope, "/") {
			scope += "/"
		}
		return expertLocalScopeResult{scope: scope, isLocal: true, validateRepo: true}, nil
	}

	if looksLikeExpertPath(input) {
		missingCandidates := make([]string, 0, 3)
		if filepath.IsAbs(input) {
			missingCandidates = append(missingCandidates, input)
		} else {
			cwdAbs, err := filepath.Abs(input)
			if err != nil {
				return expertLocalScopeResult{}, fmt.Errorf("resolve cwd-relative path: %w", err)
			}
			missingCandidates = append(missingCandidates, cwdAbs, filepath.Join(root, input))
		}
		for _, candidate := range uniqueStrings(missingCandidates) {
			scope, err := localPathScope(root, candidate, input)
			if err != nil {
				continue
			}
			return expertLocalScopeResult{scope: scope, isLocal: true}, nil
		}
		return expertLocalScopeResult{
			scope: normalizeExpertScope(input), isLocal: true,
		}, nil
	}
	return expertLocalScopeResult{}, nil
}

func localPathScope(root, candidate, original string) (string, error) {
	rel, err := filepath.Rel(canonicalPathForRel(root), canonicalPathForRel(candidate))
	if err != nil {
		return "", fmt.Errorf("relativize local scope: %w", err)
	}
	if rel == "." {
		return "./", nil
	}
	if strings.HasPrefix(rel, ".."+string(filepath.Separator)) || rel == ".." {
		return "", fmt.Errorf("path %q is outside the git worktree", original)
	}
	return filepath.ToSlash(rel), nil
}

func canonicalPathForRel(path string) string {
	resolved, err := filepath.EvalSymlinks(path)
	if err == nil {
		return resolved
	}

	var missing []string
	current := path
	for {
		parent := filepath.Dir(current)
		base := filepath.Base(current)
		if parent == current {
			return path
		}
		missing = append([]string{base}, missing...)
		resolvedParent, err := filepath.EvalSymlinks(parent)
		if err == nil {
			return filepath.Join(append([]string{resolvedParent}, missing...)...)
		}
		current = parent
	}
}

func uniqueStrings(values []string) []string {
	seen := make(map[string]bool, len(values))
	out := make([]string, 0, len(values))
	for _, value := range values {
		if seen[value] {
			continue
		}
		seen[value] = true
		out = append(out, value)
	}
	return out
}

func looksLikeExpertPath(input string) bool {
	trimmed := strings.TrimSpace(input)
	if trimmed == "" || strings.ContainsAny(trimmed, " \t\n\r") {
		return false
	}
	return strings.ContainsAny(trimmed, `/\`) ||
		strings.HasPrefix(trimmed, ".") ||
		strings.HasSuffix(trimmed, "/") ||
		filepath.Ext(trimmed) != ""
}

func normalizeExpertScope(input string) string {
	scope := strings.TrimSpace(filepath.ToSlash(input))
	scope = strings.TrimPrefix(scope, "./")
	scope = strings.TrimLeft(scope, "/")
	return scope
}

func stagedExpertScopes(ctx context.Context) ([]string, error) {
	cmd := exec.CommandContext(ctx, "git", "diff", "--cached", "--name-only", "--diff-filter=ACMRD")
	output, err := cmd.Output()
	if err != nil {
		return nil, fmt.Errorf("read staged files: %w", err)
	}
	return parseGitStagedScopeLines(string(output)), nil
}

// parseGitStagedScopeLines normalizes git name-only output into repo-relative
// path scopes. Windows git may emit CRLF line endings; strip them before split.
func parseGitStagedScopeLines(raw string) []string {
	trimmed := strings.TrimSpace(raw)
	trimmed = strings.ReplaceAll(trimmed, "\r\n", "\n")
	lines := strings.Split(trimmed, "\n")
	scopes := make([]string, 0, len(lines))
	seen := make(map[string]bool, len(lines))
	for _, line := range lines {
		scope := strings.TrimSpace(filepath.ToSlash(line))
		if scope == "" || seen[scope] {
			continue
		}
		seen[scope] = true
		scopes = append(scopes, scope)
	}
	return scopes
}

func renderExperts(w io.Writer, resp expertsResponse) {
	renderExpertsWithStyles(w, resp, newExpertsStyles(w))
}

func renderExpertsWithStyles(w io.Writer, resp expertsResponse, styles expertsStyles) {
	scopeLabel := strings.Join(resp.Scopes, ", ")
	if resp.Query != nil && strings.TrimSpace(*resp.Query) != "" {
		scopeLabel = *resp.Query
	}
	if scopeLabel == "" {
		scopeLabel = resp.RepoFullName
	}
	if len(resp.Profiles) == 0 {
		fmt.Fprintf(w, "No agent provenance found for %s.\n", styles.render(styles.file, scopeLabel))
		return
	}

	fmt.Fprintf(w, "%s for %s", styles.render(styles.title, "Agent provenance"), styles.render(styles.file, resp.RepoFullName))
	if resp.Branch != "" {
		fmt.Fprintf(w, " %s", styles.render(styles.muted, "("+resp.Branch+")"))
	}
	fmt.Fprintln(w)
	fmt.Fprintln(w)

	for i, profile := range resp.Profiles {
		if i > 0 {
			fmt.Fprintln(w)
		}
		fmt.Fprintf(w, "%s\n", styles.render(styles.agent, profile.AgentLabel))
		fmt.Fprintf(w, "  %s: %d sessions, %d matching checkpoints, %d steps", styles.render(styles.label, "evidence"), profile.SessionCount, profile.CheckpointCount, profile.StepCount)
		if profile.AttributionAgentLines != nil {
			fmt.Fprintf(w, ", %d agent-attributed lines", *profile.AttributionAgentLines)
		}
		fmt.Fprintln(w)
		writeFacetLineWithStyles(w, "skills", profile.Skills, styles)
		writeFacetLineWithStyles(w, "tools", profile.ToolMix, styles)
		writeFacetLineWithStyles(w, "mcp", profile.MCPServers, styles)
		if len(profile.MatchedFiles) > 0 {
			fmt.Fprintf(w, "  %s: %s\n", styles.render(styles.label, "files"), strings.Join(renderExpertFiles(profile.MatchedFiles, styles), ", "))
		}
		for _, session := range profile.Sessions {
			sessionURL := expertsSessionURL(resp.RepoFullName, session.SessionID)
			fmt.Fprintf(w, "  %s %s", styles.render(styles.bullet, "-"), styles.link(styles.facet, sessionURL, session.DisplayName))
			if session.CheckpointCount > 0 || session.StepCount > 0 {
				fmt.Fprintf(w, " %s %s", styles.render(styles.muted, "-"), styles.render(styles.muted, fmt.Sprintf("%d checkpoints, %d steps", session.CheckpointCount, session.StepCount)))
			}
			fmt.Fprintln(w)
		}
	}
}

func writeFacetLineWithStyles(w io.Writer, label string, facets []expertsFacetCount, styles expertsStyles) {
	if len(facets) == 0 {
		return
	}
	trimmedLabel := strings.TrimSpace(label)
	indent := label[:len(label)-len(strings.TrimLeft(label, " \t"))]
	if indent == "" {
		indent = "  "
	}
	parts := make([]string, 0, len(facets))
	for _, facet := range facets {
		if styles.colorEnabled {
			parts = append(parts, styles.render(styles.facet, facet.Name)+styles.render(styles.muted, fmt.Sprintf(" (%d)", facet.Count)))
			continue
		}
		parts = append(parts, fmt.Sprintf("%s (%d)", facet.Name, facet.Count))
	}
	fmt.Fprintf(w, "%s%s: %s\n", indent, styles.render(styles.label, trimmedLabel), strings.Join(parts, ", "))
}

func renderExpertFiles(files []string, styles expertsStyles) []string {
	if !styles.colorEnabled {
		return files
	}
	rendered := make([]string, 0, len(files))
	for _, file := range files {
		rendered = append(rendered, styles.render(styles.file, file))
	}
	return rendered
}

package cli

import (
	"context"
	"errors"
	"fmt"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/auth"
	"github.com/entireio/cli/internal/coreapi"
)

// cellResolveTimeout bounds the best-effort control-plane lookups that pick a
// repo's cell for a multi-repo fan-out (cell_fanout.go's resolveCellBaseURLs).
// Without it, a reachable-but-hung control plane would block the calling
// command instead of degrading to jurisdiction routing — the "any failure
// falls back" contract must hold for slow cores, not just erroring ones.
const cellResolveTimeout = 5 * time.Second

// requiredCellResolveTimeout bounds the control-plane lookups a repo-scoped
// cell read cannot proceed without: resolveRepoCellTarget (trails, experts)
// and resolveRepoCellPlacement (checkpoint/explain --repo).
//
// Deliberately not cellResolveTimeout: that budget bounds *best-effort*
// lookups whose failure silently degrades to jurisdiction routing, so it can
// be aggressive. Here a timeout is a visible command failure, and the budget
// has to cover two sequential control-plane round trips (a repo lookup, then
// the cluster catalog), so it is more patient.
//
// Some deadline is required: the coreapi HTTP client sets only a dial timeout,
// so a reachable-but-slow core is otherwise unbounded, and this runs before the
// command's spinner starts — the user would sit in front of a silent terminal.
const requiredCellResolveTimeout = 15 * time.Second

// cellCoreClient is the control-plane surface the cell-target resolver needs.
// An interface (with a swappable constructor) so the resolver is unit-testable
// against a fake control plane; *coreapi.Client satisfies it.
type cellCoreClient interface {
	GetRepo(ctx context.Context, params coreapi.GetRepoParams) (*coreapi.Repo, error)
	ListClusters(ctx context.Context) (*coreapi.ListClustersOutputBody, error)
	ListRepos(ctx context.Context, params coreapi.ListReposParams) (*coreapi.ListReposOutputBody, error)
}

// newCellCoreClient builds the control-plane client used for cell resolution.
// Swapped in tests.
var newCellCoreClient = func() (cellCoreClient, error) { return coreapi.New() }

// resolveRepoCellTarget resolves the entire-api cell that HOSTS the given
// repo, plus that cell's jurisdiction, so a repo-scoped call (trails, experts)
// reaches the region that owns the repo — mirroring how the entire.io BFF
// selects a cell per repo (list-repos-index.ts' processingPlacement()) rather
// than using the caller's home cell.
//
// This is NOT best-effort: every failure (control-plane error or timeout,
// repo not onboarded, no/failed/suspended processing placement, missing
// apiUrl) returns a descriptive error instead of falling back to the
// caller's home cell. A silent wrong-region "success" is worse than a command
// failure for repo-scoped data — that fallback is exactly how a mirrored repo
// like entirehq/entire.io used to read (or fail to read) the wrong region's
// trails.
//
// Placement source:
//   - ulid form: coreapi.GetRepo(ulid) -> Repo.ClusterHost, mapped by host via
//     cellTargetForClusterHost. A ULID already names one placement
//     unambiguously, so there is no processing-placement lookup to do.
//   - owner/repo form: delegates to resolveRepoCellPlacement (see its doc
//     comment for why the two functions stay separate) and discards the
//     placement id.
func resolveRepoCellTarget(ctx context.Context, fullName, ulid string) (*auth.CellTarget, error) {
	if strings.TrimSpace(ulid) != "" {
		ctx, cancel := context.WithTimeout(ctx, requiredCellResolveTimeout)
		defer cancel()

		c, err := newCellCoreClient()
		if err != nil {
			return nil, fmt.Errorf("control plane unavailable: %w", err)
		}
		repo, err := c.GetRepo(ctx, coreapi.GetRepoParams{RepoId: ulid})
		if err != nil {
			return nil, cellPlacementError(ctx, ulid, fmt.Errorf("resolve the Entire cell for %s: %w", ulid, err))
		}
		clusterHost := strings.TrimSpace(repo.ClusterHost.Or(""))
		if clusterHost == "" {
			return nil, fmt.Errorf("resolve the Entire cell for %s: repo has no cluster host", ulid)
		}
		target, err := cellTargetForClusterHost(ctx, c, clusterHost)
		if err != nil {
			return nil, cellPlacementError(ctx, ulid, fmt.Errorf("resolve the Entire cell for %s: %w", ulid, err))
		}
		return target, nil
	}

	owner, repo, ok := strings.Cut(strings.TrimSpace(fullName), "/")
	if !ok || owner == "" || repo == "" {
		return nil, fmt.Errorf("invalid repo %q: expected owner/repo", fullName)
	}
	placement, err := resolveRepoCellPlacement(ctx, owner, repo)
	if err != nil {
		return nil, err
	}
	return placement.Target, nil
}

// cellTargetForClusterHost maps a known cluster host to a cell apiUrl +
// jurisdiction via the coreapi cluster catalog, the authoritative source for a
// jurisdiction's cell URL. Used by the ULID path only: a GetRepo response
// names a cluster host, not a slug.
func cellTargetForClusterHost(ctx context.Context, c cellCoreClient, clusterHost string) (*auth.CellTarget, error) {
	clusters, err := c.ListClusters(ctx)
	if err != nil {
		return nil, fmt.Errorf("list clusters: %w", err)
	}
	cluster, ok := matchClusterByHost(clusters.Clusters, clusterHost)
	if !ok {
		return nil, fmt.Errorf("no cluster matches host %q", clusterHost)
	}
	return cellTargetFromCluster(cluster)
}

// cellTargetForPlacement maps a RepoPlacement to its cell's apiUrl +
// jurisdiction via the coreapi cluster catalog, trying the same two joins the
// multi-repo fan-out uses: ClusterSlug against Cluster.Slug first (the
// reliable key for a placement — see cell_fanout.go's groupReposByCell), then
// the placement's Cell name against the catalog's URLs.
//
// Both tiers exist because resolveCellBaseURLs — the sibling path resolving
// the same data for a repo SET — needs both in practice; its own comments name
// the misses it survives ("cluster not in catalog", "cell name does not appear
// in any catalog URL"). Joining on slug alone here made the single-repo path
// hard-fail on exactly the catalog gap the fan-out was written to tolerate,
// leaving `entire trail`, `entire experts` and `explain --repo` strictly
// narrower than `entire search`.
//
// Unlike the fan-out there is deliberately no jurisdiction-default tier: that
// is home-cell routing, i.e. the wrong-region "success" this resolver exists
// to refuse. Two joins, then a loud failure.
func cellTargetForPlacement(ctx context.Context, c cellCoreClient, placement coreapi.RepoPlacement) (*auth.CellTarget, error) {
	clusters, err := c.ListClusters(ctx)
	if err != nil {
		return nil, fmt.Errorf("list clusters: %w", err)
	}
	cluster, ok := matchClusterBySlug(clusters.Clusters, placement.ClusterSlug)
	if !ok {
		cluster, ok = matchClusterByCellInURL(clusters.Clusters, placement.Cell)
	}
	if !ok {
		return nil, fmt.Errorf("no cluster matches slug %q or cell %q", placement.ClusterSlug, placement.Cell)
	}
	return cellTargetFromCluster(cluster)
}

// cellTargetFromCluster extracts the apiUrl + jurisdiction a matched catalog
// cluster resolves to, shared by the host- and slug-keyed joins above.
func cellTargetFromCluster(cluster coreapi.Cluster) (*auth.CellTarget, error) {
	apiURL := strings.TrimRight(strings.TrimSpace(cluster.ApiUrl.Or("")), "/")
	// DNS is case-insensitive; normalise the catalog jurisdiction so a
	// non-lowercase value still passes the auth layer's strict label check
	// instead of hard-failing the target path.
	jurisdiction := strings.ToLower(strings.TrimSpace(cluster.Jurisdiction))
	if apiURL == "" || jurisdiction == "" {
		return nil, fmt.Errorf("matched cluster %q is missing apiUrl/jurisdiction", cluster.Slug)
	}
	return &auth.CellTarget{BaseURL: apiURL, Jurisdiction: jurisdiction}, nil
}

// errRepoNotOnboarded signals that fullName has no processing placement to
// resolve, in any of its three shapes: no entry at all in the control plane's
// repos index, a Candidate row (on the forge, never onboarded), or a row whose
// primaries name no processing placement. Callers that persist a per-repo
// enabled/disabled decision (trails' background enablement cache) should treat
// this the same way they'd treat an explicit "not found" from the data API,
// rather than leaving the decision unresolved forever.
//
// The third shape can be transient (a repo mid-onboarding has placements
// before its primaries are set) and is still grouped with the permanent two
// deliberately: repo-scoped data is unreachable either way, and the one
// consumer caches under a TTL, so a completed onboarding self-heals.
var errRepoNotOnboarded = errors.New("repo is not onboarded to Entire")

// resolveProcessingPlacement resolves fullName's PROCESSING placement — the
// placement id and cell entire-api and the control plane treat as
// authoritative for repo-scoped data (trails, experts, checkpoint/explain),
// mirroring the entire.io BFF's processingPlacement() selection
// (list-repos-index.ts). A repo can be mirrored in several regions; only this
// one placement is guaranteed to hold the repo's actual data.
//
// Its errors deliberately omit fullName: every caller already wraps them with
// the repo name, and naming it here too is what produced the doubled
// "resolve processing placement for X: X: repo is not onboarded" output.
func resolveProcessingPlacement(ctx context.Context, c cellCoreClient, fullName string) (coreapi.RepoPlacement, error) {
	entry, err := lookupRepoIndexEntry(ctx, c, fullName)
	if err != nil {
		return coreapi.RepoPlacement{}, err
	}
	// A Candidate row is a repo that exists on the forge and is visible to the
	// caller but was never onboarded: no placements or primaries to resolve.
	//
	// Kept as its own branch, but NOT because it is the common case — the
	// opposite is true today. The OpenAPI text on ListReposParams.Filter says
	// scope is ignored for a Filter lookup, which would make Candidate rows
	// reachable; the live control plane does not behave that way. Verified
	// against prod 2026-08-19: filter=torvalds/linux (public, plainly not
	// onboarded) returns ZERO rows, not a Candidate row, and
	// repo_mirror.go's runRepoMirrorGetByName documents the same server
	// behaviour. So the zero-rows branch above is the common real-world "not
	// onboarded" shape and this branch is currently unreachable.
	//
	// Both return errRepoNotOnboarded, so which one fires is not
	// behaviour-visible. Do not re-document this as the common case without
	// re-checking the server.
	if _, isCandidate := entry.Candidate.Get(); isCandidate {
		return coreapi.RepoPlacement{}, errRepoNotOnboarded
	}
	var processingID string
	if primaries, ok := entry.Primaries.Get(); ok {
		processingID = strings.TrimSpace(primaries.Processing)
	}
	if processingID == "" {
		return coreapi.RepoPlacement{}, errRepoNotOnboarded
	}
	// Shares the fan-out's matcher (cell_fanout.go) so the two resolvers can
	// never disagree on whether an ID names a placement — only on what they
	// do with the answer, which is the deliberate part (see below).
	p, ok := placementByID(entry.Placements, processingID)
	if !ok {
		// Defensive: primaries.processing should always name a placement
		// present in the same response.
		return coreapi.RepoPlacement{}, fmt.Errorf("processing placement %q is not in the repo's placement list", processingID)
	}
	if p.Status == coreapi.RepoPlacementStatusFailed || p.Status == coreapi.RepoPlacementStatusSuspended {
		return coreapi.RepoPlacement{}, fmt.Errorf("processing placement is %s", p.Status)
	}
	return p, nil
}

// lookupRepoIndexEntry is the exact-match repo-index lookup shared by every
// resolver that starts from an owner/repo name. Zero rows is
// errRepoNotOnboarded (see resolveProcessingPlacement for why that, not a
// Candidate row, is the real-world "not onboarded" shape).
//
// Filter is documented as an exact-match lookup restricted to fullName, so
// beyond the identity check and the zero-length check, Repos[0] is the only
// possible row. The check exists because that promise lives only in the
// OpenAPI doc, not in this code: if the control plane ever ignored or dropped
// Filter, the entry could silently be an unrelated repo — exactly the
// wrong-region-success bug class these resolvers exist to kill.
func lookupRepoIndexEntry(ctx context.Context, c cellCoreClient, fullName string) (coreapi.RepoIndexEntry, error) {
	out, err := c.ListRepos(ctx, coreapi.ListReposParams{Filter: coreapi.NewOptString(fullName)})
	if err != nil {
		return coreapi.RepoIndexEntry{}, fmt.Errorf("list repos: %w", err)
	}
	if len(out.Repos) == 0 {
		return coreapi.RepoIndexEntry{}, errRepoNotOnboarded
	}
	entry := out.Repos[0]
	if !strings.EqualFold(strings.TrimSpace(entry.FullName), strings.TrimSpace(fullName)) {
		return coreapi.RepoIndexEntry{}, fmt.Errorf("control plane returned %q for %s", entry.FullName, fullName)
	}
	return entry, nil
}

// repoCellPlacement is a repo's processing placement: the id entire-api keys
// repo-scoped routes on, paired with the cell that actually holds it.
type repoCellPlacement struct {
	// RepoID is the placement id (coreapi.RepoPlacement.ID), which entire-api
	// uses as its repo_id — verified identical to the id the old
	// mirrors-based lookup used (coreapi.Mirror.MirrorId) for the same
	// placement.
	RepoID string
	// Target is the cell hosting THIS placement.
	Target *auth.CellTarget
}

// resolveRepoCellPlacement resolves a GitHub repo to its processing
// placement's (repo_id, cell) pair for repo-scoped cell reads.
//
// The pair must come from the same placement: a placement id is only
// resolvable by the cell hosting that placement, and entire-api's data lives
// on exactly one placement (the processing one) even when the repo is
// mirrored elsewhere too. Taking the id from one placement and routing to a
// cell chosen some other way asks a cell about an id it has never seen, which
// comes back as an indistinguishable 404.
//
// resolveRepoCellTarget's owner/repo path delegates to this function and
// discards RepoID, rather than the two duplicating the same resolution body:
// the two functions exist separately only because their callers need
// different return shapes for the same lookup — this one also needs the
// placement id (repo_id), which resolveRepoCellTarget has no caller for and
// so doesn't return — not because the resolution logic itself differs.
func resolveRepoCellPlacement(ctx context.Context, owner, repo string) (repoCellPlacement, error) {
	ctx, cancel := context.WithTimeout(ctx, requiredCellResolveTimeout)
	defer cancel()

	c, err := newCellCoreClient()
	if err != nil {
		return repoCellPlacement{}, fmt.Errorf("control plane unavailable: %w", err)
	}
	fullName := owner + "/" + repo
	placement, err := resolveProcessingPlacement(ctx, c, fullName)
	if err != nil {
		return repoCellPlacement{}, cellPlacementError(ctx, fullName, fmt.Errorf("resolve processing placement for %s: %w", fullName, err))
	}
	target, err := cellTargetForPlacement(ctx, c, placement)
	if err != nil {
		return repoCellPlacement{}, cellPlacementError(ctx, fullName, fmt.Errorf("resolve cell for %s: %w", fullName, err))
	}
	// Trimmed for the same reason the match is: RepoID becomes a path segment
	// in entire-api URLs, so tolerating a padded id in the lookup without
	// normalizing it here would trade a loud "not in the placement list" for
	// a malformed request.
	return repoCellPlacement{RepoID: strings.TrimSpace(placement.ID), Target: target}, nil
}

// cellPlacementError reports a timeout as a timeout: without this, a fired
// deadline surfaces as whichever "not found"/"no processing placement" error
// the caller's lookup happened to return, and the user goes looking for a
// missing mirror instead of a slow control plane. subject is the repo the
// lookup was for, named however the caller addressed it (owner/repo or ULID).
//
// Only DeadlineExceeded is relabelled. A cancelled context is a Ctrl+C, not a
// timeout, and calling it one sends the user hunting a slow control plane that
// was never the problem; the cancelled in-flight call's own error already
// carries context.Canceled, which is what renderDataAPIAuthError silences on.
func cellPlacementError(ctx context.Context, subject string, fallback error) error {
	if ctxErr := ctx.Err(); errors.Is(ctxErr, context.DeadlineExceeded) {
		return fmt.Errorf("resolving the Entire cell for %s timed out: %w", subject, ctxErr)
	}
	return fallback
}

// isActiveMirror reports whether a mirror placement can currently serve the
// repo: not archived, and not in a failed/suspended clone state. An unset status
// is treated as active (older data). Shared by every caller that must ignore
// placements a cell can't answer for.
func isActiveMirror(m coreapi.Mirror) bool {
	if m.IsArchived.Or(false) {
		return false
	}
	st := m.Status.Or(coreapi.MirrorStatusReady)
	return st != coreapi.MirrorStatusFailed && st != coreapi.MirrorStatusSuspended
}

// matchClusterByHost finds the catalog cluster whose public host equals
// clusterHost (case-insensitive). The cluster's apiUrl + jurisdiction are the
// authoritative cell coordinates. Used by the ULID path (GetRepo returns a
// host, not a slug).
func matchClusterByHost(clusters []coreapi.Cluster, clusterHost string) (coreapi.Cluster, bool) {
	want := strings.ToLower(strings.TrimSpace(clusterHost))
	if want == "" {
		return coreapi.Cluster{}, false
	}
	for _, cl := range clusters {
		host, err := hostFromPublicURL(cl.PublicUrl)
		if err != nil {
			continue
		}
		if strings.EqualFold(strings.TrimSpace(host), want) {
			return cl, true
		}
	}
	return coreapi.Cluster{}, false
}

// matchClusterBySlug finds the catalog cluster whose Slug equals clusterSlug
// (case-insensitive). Used by the owner/repo path: a RepoPlacement carries a
// ClusterSlug, not a host, so this is the reliable join for it (the catalog
// does not expose a cell field, so slug — not cell name — is the only
// reliable join key; see cell_fanout.go's groupReposByCell for the same rule).
func matchClusterBySlug(clusters []coreapi.Cluster, clusterSlug string) (coreapi.Cluster, bool) {
	want := strings.ToLower(strings.TrimSpace(clusterSlug))
	if want == "" {
		return coreapi.Cluster{}, false
	}
	for _, cl := range clusters {
		if strings.EqualFold(strings.TrimSpace(cl.Slug), want) {
			return cl, true
		}
	}
	return coreapi.Cluster{}, false
}

package cli

import (
	"context"
	"errors"
	"fmt"

	"github.com/entireio/cli/cmd/entire/cli/api"
	"github.com/entireio/cli/cmd/entire/cli/auth"
	"github.com/entireio/cli/internal/entireclient/clusterdiscovery"
)

// NewAuthenticatedAPIClient creates an API client targeting api.BaseURL()
// (the data API origin) carrying the matching login context's account access
// token (see auth.ResolveDataAPIToken).
//
// Pass insecureHTTP=true to allow plain HTTP base URLs for local
// development. Only the data origin is checked here — the bearer travels
// there on resource requests; the refresh leg is guarded by the per-context
// token manager (https required outside loopback/opt-in).
func NewAuthenticatedAPIClient(ctx context.Context, insecureHTTP bool) (*api.Client, error) {
	dataURL := api.BaseURL()
	if insecureHTTP {
		auth.EnableInsecureHTTP()
	} else if err := api.RequireSecureURL(dataURL); err != nil {
		return nil, fmt.Errorf("base URL check: %w", err)
	}

	// ResolveDataAPIToken discovers which login context the data host trusts
	// (via its /.well-known/entire-api.json) and returns that context's
	// refreshed login JWT. It normalises dataURL to an origin internally.
	token, err := auth.ResolveDataAPIToken(ctx, dataURL)
	if err != nil {
		if errors.Is(err, auth.ErrNotLoggedIn) {
			// Wrap the original err (not the sentinel) so any context
			// the tokenmanager attached — keyring backend message,
			// expired-token reason — survives to the caller. The
			// errors.Is(err, auth.ErrNotLoggedIn) chain is preserved
			// because err already wraps the sentinel; replacing it
			// with the bare sentinel would drop that context for
			// zero behavioural gain.
			return nil, fmt.Errorf("not logged in (run 'entire login' first): %w", err)
		}
		return nil, fmt.Errorf("resolve API token: %w", err)
	}

	return api.NewClient(token), nil
}

// NewAuthenticatedEntireAPICellClient creates an API client for repo-scoped
// entire-api routes (e.g. trails, experts). It exchanges the login JWT for a
// jurisdictional identity token and dials the entire-api cell directly, because
// the BFF does not proxy these routes for bearer callers (COR-666).
//
// fullName (owner/repo) or ulid identifies the repo whose cell to reach; ulid
// wins when both are set, and both being empty is an error, not a fallback to
// the caller's home cell. The repo's PROCESSING cell + jurisdiction are
// resolved from the control plane
// (mirroring the BFF's per-repo cell selection) so the call lands in the
// region that actually holds the repo's data. This is NOT best-effort: a
// resolution failure fails the command instead of falling back to the
// caller's home cell, because for repo-scoped data a silent wrong-region
// "success" is worse than an error — that fallback is exactly what used to
// make `entire trail`/`entire experts` read the wrong region for a
// multi-homed repo like entirehq/entire.io.
func NewAuthenticatedEntireAPICellClient(ctx context.Context, insecureHTTP bool, fullName, ulid string) (*api.Client, error) {
	target, err := resolveRepoCellTarget(ctx, fullName, ulid)
	if err != nil {
		return nil, err
	}
	// NewEntireAPICellClient already returns user-facing, context-rich errors
	// (login hint, discovery-unavailable, region guidance); re-wrapping here
	// would bury them, so surface them verbatim.
	return auth.NewEntireAPICellClient(ctx, insecureHTTP, target) //nolint:wrapcheck // pass through contextual auth errors
}

// newTrailAPIClient dials the entire-api cell that owns the repository. It is a
// package seam so tests can substitute a client pointed at a stub server.
var newTrailAPIClient = func(ctx context.Context, insecureHTTP bool, fullName string) (*api.Client, error) {
	client, err := NewAuthenticatedEntireAPICellClient(ctx, insecureHTTP, fullName, "")
	if errors.Is(err, clusterdiscovery.ErrNoAuthContext) {
		// Preserve cluster discovery's detailed host/context hint while restoring
		// the sentinel trail commands use for the standard login UX.
		return nil, fmt.Errorf("%w: %w", auth.ErrNotLoggedIn, err)
	}
	if err != nil {
		return nil, err
	}
	return client, nil
}

