func TestExpertsCommandOwnerRepoResolvesViaControlPlanePlacement(t *testing.T) {
	fake := &fakeExpertsClient{body: `{"repo_full_name":"acme/widget","scopes":["api/x.go"],"query":null,"branch":"main","source":"db","profiles":[]}`}
