	root.SetArgs([]string{"experts", "api/x.go", "--repo", "acme/widget", "--json"})

	if err := root.Execute(); err != nil {
		t.Fatalf("execute experts: %v", err)
	}
	if fake.gotPath != expertsAPIReposPath+"/"+expertsTestRepoULID+"/experts" {
		t.Fatalf("path = %q, want the control-plane-resolved placement id", fake.gotPath)
	}
	if cellFake.lastListReposParams.Filter.Or("") != "acme/widget" {
		t.Fatalf("expected the control plane's repo index to be queried for acme/widget, got Filter=%q", cellFake.lastListReposParams.Filter.Or(""))
	}
	if cellFake.repo != nil && cellFake.repoErr == nil {
		// GetRepo (the ULID lookup) is a distinct method; owner/repo form must
		// never call it. fakeCellCore always returns the configured repo
		// regardless of caller, so absence is enforced by runExperts' branch
		// (repoIsULID), not observable here — this assertion just documents
		// the invariant the branch exists to guarantee.
		_ = cellFake.repo
	}
}

